from pathlib import Path
import subprocess

GOOD_COMMIT = 'd38fad527571de30d55aa728beb097d14b9bd1ab'
index = Path('index.html')
html = subprocess.check_output(['git','show',f'{GOOD_COMMIT}:index.html'], text=True)

old = '''function pulseVisual(s,i){return `<article class="slide pulse-slide"><div class="art" id="pulseArt-${i}">${s.image_b64?`<img src="data:${esc(s.image_mime_type||'image/jpeg')};base64,${s.image_b64}" alt="Cyber Pulse artwork">`:'<div class="placeholder">المشهد البصري بدون نص — اضغط إنشاء الصور</div>'}<div class="overlay"><div class="overlay-head">${esc(s.headline)}</div><div class="overlay-body">${esc(s.body)}</div><div class="overlay-footer">نبض سيبراني | Cyber Pulse</div><div class="slide-no">${esc(s.number)}</div></div></div><div class="slide-info"><h4>${esc(s.headline)}</h4><p>${esc(s.body)}</p><div class="slide-actions"><button data-pulse-img="${i}">إنشاء/إعادة الصورة</button></div></div></article>`}'''
new = '''function pulseVisual(s,i){return `<article class="slide pulse-slide"><div class="art" id="pulseArt-${i}">${s.image_b64?`<img src="data:${esc(s.image_mime_type||'image/jpeg')};base64,${s.image_b64}" alt="Cyber Pulse artwork">`:'<div class="placeholder">المشهد البصري بدون نص — اضغط إنشاء الصور</div>'}<div class="overlay"><div class="overlay-head">${esc(s.headline)}</div><div class="overlay-body">${esc(s.body)}</div><div class="overlay-footer">نبض سيبراني | Cyber Pulse</div><div class="slide-no">${esc(s.number)}</div></div></div><div class="slide-info"><h4>${esc(s.headline)}</h4><p>${esc(s.body)}</p><div class="slide-actions"><button data-pulse-img="${i}">إنشاء/إعادة الصورة</button>${s.image_b64?`<button data-pulse-download="${i}" title="تحميل الصورة النهائية مع النص">⬇ تحميل الصورة</button>`:''}</div></div></article>`}'''
if old not in html:
    raise SystemExit('pulseVisual block not found in good index')
html = html.replace(old, new, 1)

old_render = '''function renderPulseResult(){if(!pulseCurrent)return;const d=pulseCurrent.data,r=$('pulseResult'),meta=pulseCurrent.meta;r.classList.remove('hidden');r.innerHTML=`<div class="pulse-panel"><div class="section-title"><div><div class="pulse-meta">${esc(meta.pillar)} • ${esc(meta.domain)} • ${esc(meta.format)} • ${esc(meta.objective)}</div><h2 style="margin:0">${esc(d.title||pulseCurrent.topic)}</h2></div><span class="counter">${esc(meta.platform)}</span></div>${d.hook?`<p>${esc(d.hook)}</p>`:''}<div class="slides">${(d.slides||[]).map(pulseVisual).join('')}</div><h3>النص الجاهز للنشر</h3><div class="pulse-caption">${esc(pulseText(d))}</div>${meta.format==='Guide + PDF'?'<div class="pulse-note">تم تجهيز محتوى الدليل والشرائح. توليد ملف PDF الداعم سيتم ربطه في الخطوة التالية من نفس القسم.</div>':''}</div>`;r.querySelectorAll('[data-pulse-img]').forEach(b=>b.onclick=()=>generatePulseImage(Number(b.dataset.pulseImg),true));$('pulseGenerateImages').classList.toggle('hidden',!(d.slides||[]).length);$('pulseCopy').classList.remove('hidden')}'''

new_render = r'''function pulseLoadImage(src){return new Promise((ok,no)=>{const im=new Image();im.onload=()=>ok(im);im.onerror=no;im.src=src})}
function pulseWrapLines(ctx,text,maxWidth,maxLines){const words=String(text||'').trim().split(/\s+/).filter(Boolean),lines=[];let line='';for(const word of words){const test=line?line+' '+word:word;if(line&&ctx.measureText(test).width>maxWidth){lines.push(line);line=word;if(lines.length>=maxLines)break}else line=test}if(lines.length<maxLines&&line)lines.push(line);if(words.length&&lines.length===maxLines){let last=lines[maxLines-1];while(last.length>1&&ctx.measureText(last+'…').width>maxWidth)last=last.slice(0,-1);lines[maxLines-1]=last+'…'}return lines.slice(0,maxLines)}
function pulseRoundRect(ctx,x,y,w,h,r){const rr=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+rr,y);ctx.arcTo(x+w,y,x+w,y+h,rr);ctx.arcTo(x+w,y+h,x,y+h,rr);ctx.arcTo(x,y+h,x,y,rr);ctx.arcTo(x,y,x+w,y,rr);ctx.closePath()}
async function buildPulseFinalImage(i){if(!pulseCurrent)return null;const s=pulseCurrent.data.slides[i];if(!s?.image_b64)return null;await document.fonts?.ready;const W=1080,H=1350,canvas=document.createElement('canvas');canvas.width=W;canvas.height=H;const ctx=canvas.getContext('2d');const im=await pulseLoadImage(`data:${s.image_mime_type||'image/jpeg'};base64,${s.image_b64}`);const scale=Math.max(W/im.naturalWidth,H/im.naturalHeight),dw=im.naturalWidth*scale,dh=im.naturalHeight*scale;ctx.drawImage(im,(W-dw)/2,(H-dh)/2,dw,dh);
ctx.direction='rtl';ctx.textAlign='right';ctx.textBaseline='top';
ctx.fillStyle='rgba(5,11,20,.90)';pulseRoundRect(ctx,55,105,970,190,18);ctx.fill();ctx.strokeStyle='rgba(0,212,255,.45)';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#F2FBFF';ctx.font='800 48px Cairo, Arial';pulseWrapLines(ctx,s.headline,880,2).forEach((line,n)=>ctx.fillText(line,970,140+n*62));
ctx.fillStyle='rgba(5,11,20,.90)';pulseRoundRect(ctx,55,1010,970,215,18);ctx.fill();ctx.strokeStyle='rgba(21,101,192,.5)';ctx.stroke();ctx.fillStyle='#F2FBFF';ctx.font='600 29px Cairo, Arial';pulseWrapLines(ctx,s.body,880,4).forEach((line,n)=>ctx.fillText(line,970,1042+n*43));
ctx.fillStyle='rgba(5,11,20,.92)';pulseRoundRect(ctx,510,1250,515,58,14);ctx.fill();ctx.fillStyle='#65EAFF';ctx.font='700 27px Cairo, Arial';ctx.fillText('نبض سيبراني | Cyber Pulse',985,1262);
ctx.fillStyle='#00D4FF';ctx.beginPath();ctx.arc(82,1279,31,0,Math.PI*2);ctx.fill();ctx.fillStyle='#03121A';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='800 25px Cairo, Arial';ctx.fillText(String(s.number||i+1),82,1279);
return canvas.toDataURL('image/jpeg',0.95)}
async function downloadPulseImage(i){if(!pulseCurrent)return;const status=$('pulseMsg');if(status)status.textContent=`جاري تجهيز الصورة ${i+1} بالنص...`;try{const dataUrl=await buildPulseFinalImage(i);if(!dataUrl)throw new Error('الصورة غير جاهزة');const a=document.createElement('a');a.href=dataUrl;a.download=`cyber-pulse-${String(i+1).padStart(2,'0')}-final.jpg`;document.body.appendChild(a);a.click();a.remove();if(status)status.textContent=`تم تحميل الصورة ${i+1} بالنص والهوية.`}catch(e){if(status)status.textContent='تعذر تجهيز الصورة النهائية: '+e.message}}
function renderPulseResult(){if(!pulseCurrent)return;const d=pulseCurrent.data,r=$('pulseResult'),meta=pulseCurrent.meta;r.classList.remove('hidden');r.innerHTML=`<div class="pulse-panel"><div class="section-title"><div><div class="pulse-meta">${esc(meta.pillar)} • ${esc(meta.domain)} • ${esc(meta.format)} • ${esc(meta.objective)}</div><h2 style="margin:0">${esc(d.title||pulseCurrent.topic)}</h2></div><span class="counter">${esc(meta.platform)}</span></div>${d.hook?`<p>${esc(d.hook)}</p>`:''}<div class="slides">${(d.slides||[]).map(pulseVisual).join('')}</div><h3>النص الجاهز للنشر</h3><div class="pulse-caption">${esc(pulseText(d))}</div>${meta.format==='Guide + PDF'?'<div class="pulse-note">تم تجهيز محتوى الدليل والشرائح. توليد ملف PDF الداعم سيتم ربطه في الخطوة التالية من نفس القسم.</div>':''}</div>`;r.querySelectorAll('[data-pulse-img]').forEach(b=>b.onclick=()=>generatePulseImage(Number(b.dataset.pulseImg),true));r.querySelectorAll('[data-pulse-download]').forEach(b=>b.onclick=()=>downloadPulseImage(Number(b.dataset.pulseDownload)));$('pulseGenerateImages').classList.toggle('hidden',!(d.slides||[]).length);$('pulseCopy').classList.remove('hidden')}'''
if old_render not in html:
    raise SystemExit('renderPulseResult block not found in good index')
html = html.replace(old_render, new_render, 1)

index.write_text(html, encoding='utf-8')
print('Restored index.html and changed Cyber Pulse download to a final text-composited JPEG.')
